önetimi</h1><p>Kodlar veritabanında şifreli saklanır. Aynı ürün için yinelenen kodlar eklenmez.</p></div></div><form class="admin-form" method="post"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="import_codes"><label>Ürün<select name="product_id" required><option value="">Ürün seçin</option><?php foreach($inventoryProducts as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($p['name']) ?></option><?php endforeach; ?></select></label><label>Dijital kodlar <small>Her satıra bir kod girin.</small><textarea name="codes" rows="8" required placeholder="KOD-XXXX-XXXX&#10;KOD-YYYY-YYYY"></textarea></label><button type="submit">Kodları güvenli şekilde içe aktar</button></form><div class="table-wrap"><table><thead><tr><th>Ürün</th><th>Teslimat</th><th>Hazır</th><th>Rezerve</th><th>Satıldı</th></tr></thead><tbody><?php foreach($inventoryRows as $row): ?><tr><td><strong><?= e($row['name']) ?></strong></td><td><?= e($row['delivery_type']) ?></td><td><?= (int)$row['available'] ?></td><td><?= (int)$row['reserved'] ?></td><td><?= (int)$row['sold'] ?></td></tr><?php endforeach; ?><?php if(!$inventoryRows): ?><tr><td colspan="5">Henüz ürün bulunmuyor.</td></tr><?php endif; ?></tbody></table></div><?php else: ?><div class="page-head"><div><h1><?= e($meta[$resource]['title']) ?></h1><p>Kayıtları ekleyin, düzenleyin ve yayın durumlarını yönetin.</p></div><a class="primary-link" href="<?= e(url('admin?section='.$resource.'&new=1')) ?>">+ Yeni kayıt</a></div><?php if(isset($_GET['new'])||$edit): ?><form class="admin-form" method="post"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><?php foreach($meta[$resource]['fields'] as $field=>$label): ?><label><?= e($label) ?><?php if(in_array($field,['description','content','short_description'],true)): ?><textarea name="<?= e($field) ?>" rows="<?= $field==='content'?8:3 ?>"><?= e($edit[$field]??'') ?></textarea><?php elseif($field==='category_id'): ?><select name="category_id"><option value="">Kategori seçin</option><?php foreach($categories as $cat): ?><option value="<?= (int)$cat['id'] ?>" <?= (string)($edit['category_id']??'')===(string)$cat['id']?'selected':'' ?>><?= e($cat['name']) ?></option><?php endforeach; ?></select><?php elseif($field==='status'): ?><select name="status"><?php foreach(['active'=>'Yayında','draft'=>'Taslak','inactive'=>'Pasif'] as $v=>$l): ?><option value="<?= e($v) ?>" <?= ($edit[$field]??'active')===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select><?php elseif($field==='delivery_type'): ?><select name="delivery_type"><option value="manual">Manuel</option><option value="automatic" <?= ($edit[$field]??'')==='automatic'?'selected':'' ?>>Otomatik kod</option></select><?php else: ?><input name="<?= e($field) ?>" value="<?= e($edit[$field]??'') ?>" <?= in_array($field,['name','title','slug','price'],true)?'required':'' ?>><?php endif; ?></label><?php endforeach; ?><div class="form-actions"><button type="submit">Kaydet</button><a href="<?= e(url('admin?section='.$resource)) ?>">Vazgeç</a></div></form><?php endif; ?><div class="table-wrap"><table><thead><tr><th>#</th><th>Başlık</th><th>Durum</th><th>İşlem</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= (int)$row['id'] ?></td><td><strong><?= e($row['name']??$row['title']??'') ?></strong><small><?= e($row['slug']??$row['url']??'') ?></small></td><td><span class="status"><?= e($row['status']??'') ?></span></td><td class="actions"><a href="<?= e(url('admin?section='.$resource.'&edit='.(int)$row['id'])) ?>">Düzenle</a><form method="post" onsubmit="return confirm('Bu kayıt silinsin mi?')"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="link-danger" type="submit">Sil<